const j = $input.first().json;
const tryParse = (v) => {
  if (v && typeof v === 'object') return v;
  if (typeof v !== 'string' || !v.trim()) return null;
  const s = v.trim().replace(/^\x60{3}(?:json)?\s*/i, '').replace(/\s*\x60{3}$/, '');
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{');
  const b = s.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
};
const joinParts = (c) => (c && Array.isArray(c.parts)) ? c.parts.map(p => p.text || '').join('') : undefined;
const candidates = [
  joinParts(j.content),
  (j.content && typeof j.content === 'object' && !j.content.parts) ? j.content : undefined,
  typeof j.content === 'string' ? j.content : undefined,
  j.text,
  j.output,
  j.response,
  j.message && j.message.content,
  j.candidates && j.candidates[0] ? joinParts(j.candidates[0].content) : undefined
];
let out = null;
for (const c of candidates) { out = tryParse(c); if (out) break; }
if (!out && !j.error && !j.content && !j.candidates && Object.keys(j).length > 0) out = j;
const blocked = Boolean(j.promptFeedback && j.promptFeedback.blockReason);
return [{ json: { ok: Boolean(out) && !blocked, out: blocked ? null : out, error: out && !blocked ? null : (blocked ? 'blocked_by_safety' : 'unparseable_model_output') } }];
